package main

func baselineNorms() ([]normRule, []normSource) {
	const huur = "https://www.huurcommissie.nl/support/onderhoud-en-gebreken-check"
	const beleid = "https://www.huurcommissie.nl/support/beleidsboeken/gebreken/voorwoord"
	const nen = "https://www.nen.nl/bouw/beheer-en-onderhoud/conditiemeting/achtergrond-conditiemeting"
	const onderhoud = "https://www.rijksoverheid.nl/themas/bouwen-en-wonen/woning-verhuren/woning-verhuren-wat-moet-ik-regelen/vraag-en-antwoord/woning-huren/welke-kosten-zijn-voor-de-huurder-en-welke-voor-de-verhuurder"
	type entry struct {
		code, title, object, accept, reject, look, good, bad, priority string
		rooms                                                          []string
	}
	data := []entry{
		{"VOCHT", "Vocht en schimmelsporen", "Wanden en plafonds", "Het getoonde oppervlak is droog en heeft geen zichtbare vocht- of schimmelachtige plekken.", "Zichtbare vochtplekken, schimmelachtige aanslag of een vastgelegde actieve lekkage vragen opvolging.", "Beschrijf plek en zichtbare verschijnselen. Leid oorzaak, omvang buiten beeld of gezondheidseffecten niet af. Een droog detail bewijst niet dat de hele ruimte vrij van vochtproblemen is.", "Overzicht en detail tonen een droge wand zonder verkleuring.", "Donkere vlekken en vochtverkleuring zijn zichtbaar in een plafondhoek.", "high", []string{"*"}},
		{"VENT", "Ventilatieopeningen", "Ventilatieroosters en afzuigpunten", "Een getoond rooster is aanwezig, zichtbaar open en niet geblokkeerd. Werking is apart door de inspecteur gecontroleerd waar vereist.", "Een zichtbaar dichtgezet of zwaar vervuild rooster of een vastgelegde storing voldoet niet aan de gekozen functionele kwaliteit.", "Scheid zichtbare vrije doorgang van gemeten werking. Bepaal geen capaciteit uit een foto. Een bewonersmelding is een melding, geen uitgevoerde meting.", "Het rooster is schoon en open; de inspecteur beschrijft een uitgevoerde werkingstest.", "Het afzuigpunt is zichtbaar afgeplakt en de inspecteur meldt dat afzuiging ontbreekt.", "medium", []string{"Badkamer", "Toilet", "Keuken", "Slaapkamer", "Woonkamer"}},
		{"KIT", "Kit- en aansluitvoegen", "Natte aansluitingen", "De getoonde kitvoeg sluit aaneengesloten aan zonder openstaande delen.", "Een zichtbare onderbreking, loslating of open aansluiting moet worden beoordeeld voor herstel.", "Kijk naar hechting en continuïteit. Alleen verkleuring is geen bewijs van lekkage. Beoordeel geen onzichtbare waterdichting.", "Een detail toont een doorlopende voeg die aan beide zijden aansluit.", "Langs de douchebak staat een deel van de voeg zichtbaar los.", "medium", []string{"Badkamer", "Toilet", "Keuken"}},
		{"SAN", "Sanitair en aansluitingen", "Toilet, wastafel en douche", "De getoonde onderdelen zijn intact; een vastgelegde functionele controle meldt geen lekkage of loszitten.", "Een breuk, scherpe beschadiging, zichtbare lekkage of door de inspecteur vastgesteld loszitten is niet acceptabel.", "Een foto bewijst geen spoel- of afvoerwerking. Gebruik alleen een beschreven test als functioneel bewijs en houd bewonersverklaringen herkenbaar.", "Wastafel en sifon zijn intact; tijdens de beschreven proef blijft de aansluiting droog.", "Er ligt een verse waterdruppel bij een aansluiting tijdens de vastgelegde proef.", "high", []string{"Badkamer", "Toilet", "Keuken"}},
		{"KEUKEN", "Keukenonderdelen", "Kasten en werkblad", "Normale gebruikssporen zijn toegestaan wanneer het onderdeel heel en bruikbaar blijft.", "Een loshangend onderdeel, scherpe beschadiging of open aantasting van het werkblad vraagt herstelbeoordeling.", "Beoordeel de staat van het getoonde onderdeel, niet smaak, ouderdom of moderniteit. Veronderstel geen verborgen bevestigingsgebrek.", "Een kastfront heeft lichte gebruikssporen en is volgens de inspecteur goed te bedienen.", "Een kastdeur hangt scheef met een zichtbaar los scharnier.", "medium", []string{"Keuken"}},
		{"KOZIJN", "Ramen, deuren en kozijnen", "Kozijnen en hang- en sluitwerk", "De getoonde delen zijn heel; een beschreven bedieningstest bevestigt openen en sluiten.", "Een zichtbaar los onderdeel, beschadigde sluiting of vastgelegde blokkade vraagt opvolging.", "Een foto kan een sluitproef niet vervangen. Benoem houtaantasting als vermoeden wanneer alleen het oppervlak zichtbaar is. Trek geen conclusie over inbraakwerendheid.", "Het kozijn heeft alleen lichte verfslijtage en de inspecteur bevestigt een geslaagde sluitproef.", "De sluiting is zichtbaar afgebroken; de inspecteur meldt dat het raam niet sluit.", "high", []string{"*"}},
		{"AFWERK", "Wand- en plafondafwerking", "Binnenafwerking", "Lichte, stabiele gebruikssporen zonder losse delen passen binnen dit voorgestelde kwaliteitsniveau.", "Loslatende afwerking, scherpe losse delen of duidelijke beschadiging buiten gewone gebruikssporen vragen beoordeling.", "Onderscheid cosmetische slijtage van loszittend materiaal. Leid geen constructieve oorzaak uit een scheur af en schat geen maat zonder schaal.", "De wand toont kleine oppervlakkige gebruikssporen zonder losse randen.", "Een strook pleisterwerk hangt zichtbaar los boven een doorgang.", "medium", []string{"*"}},
		{"VLOER", "Vloer en loopvlak", "Vloerafwerking en drempels", "Het getoonde loopvlak heeft geen zichtbare losse delen of opstaande randen.", "Een losse tegel, opstaande vloerrand of een zichtbaar gat in het loopvlak vraagt herstelbeoordeling.", "Beoordeel alleen het zichtbare loopvlak. Bepaal geen vlakheid, stroefheid of draagkracht uit beeld. Een afgedekt deel is niet beoordeeld.", "Overzicht en detail tonen een gesloten vloer zonder opstaande randen.", "Bij een doorgang steekt een losse vloerrand omhoog.", "high", []string{"*"}},
		{"ELEKTRA", "Zichtbare elektrische afwerking", "Schakelaars, wandcontactdozen en bedrading", "De getoonde behuizing is heel en gesloten zonder zichtbare losse bedrading.", "Een ontbrekende afdekking, zichtbare beschadigde bedrading of brandspoor vraagt deskundige opvolging.", "Verklaar een installatie nooit elektrisch veilig op grond van foto's. Benoem zichtbare signalen en vraag deskundige controle; adviseer geen ingrepen.", "De wandcontactdoos heeft een complete, onbeschadigde afdekking.", "Een afdekplaat ontbreekt en bedrading is zichtbaar.", "high", []string{"*"}},
		{"MELDER", "Rookmelder vastleggen", "Rookmelder", "De getoonde melder is aanwezig en intact; de inspecteur heeft een test beschreven als werking wordt beoordeeld.", "Een zichtbaar ontbrekende behuizing, een beschadigde melder of een vastgelegde mislukte test vraagt opvolging.", "Geen melder in een foto betekent niet dat deze in de woning ontbreekt. Beoordeel geen volledige dekking, levensduur of wettelijke conformiteit zonder aanvullende gegevens.", "Een intacte melder is gefotografeerd; de inspecteur beschrijft een geslaagde test met de testknop.", "Er is alleen een lege montageplaat zichtbaar en de inspecteur bevestigt dat de melder ontbreekt.", "high", []string{"Entree", "Gang", "Overloop"}},
		{"BUITEN", "Buitenschil en afwatering", "Gevel, goten en buitenruimte", "De getoonde delen hebben geen zichtbare losse elementen of blokkade van een afvoerpunt.", "Een zichtbaar los geveldeel, gebroken gootdeel of geblokkeerd afvoerpunt vraagt opvolging.", "Beoordeel uitsluitend zichtbaar materiaal. Leid geen funderingsschade, verborgen daklekkage of oorzakelijk verband met bomen af zonder onderzoek.", "Een detail toont een vrij afvoerpunt en intacte gootaansluiting.", "Bladeren blokkeren zichtbaar een afvoerpunt; de inspecteur meldt waterophoping.", "medium", []string{"Buitenruimte", "Balkon", "Tuin", "Gevel", "Dak"}},
		{"TRAP", "Trap en leuning", "Trap, leuning en balustrade", "De getoonde onderdelen zijn compleet; vastzitten is door de inspecteur gecontroleerd waar nodig.", "Een zichtbare ontbrekende trede, onderbroken leuning of door de inspecteur vastgesteld loszitten vraagt opvolging.", "Een foto bewijst geen bevestigingssterkte. Een niet uitgevoerde stabiliteitsproef blijft een inspectiebeperking. Leid geen hoogtes of wettelijke maatvoering af zonder meting.", "De leuning is compleet; de inspecteur beschrijft dat deze bij controle vast bleef zitten.", "De leuningbeugel is zichtbaar los en de inspecteur bevestigt beweging bij controle.", "high", []string{"Entree", "Gang", "Overloop", "Trap"}},
	}
	rules := []normRule{}
	for _, e := range data {
		rules = append(rules, normRule{ID: id(), Code: e.code, Title: e.title, Rooms: e.rooms, ObjectType: e.object, Acceptable: e.accept, Unacceptable: e.reject, AIGuidance: e.look, Modalities: []string{"photo", "audio"}, Priority: e.priority, SourceURLs: []string{huur, nen}, Examples: []normExample{{ID: id(), Outcome: "acceptable", Caption: e.good}, {ID: id(), Outcome: "unacceptable", Caption: e.bad}}})
	}
	return rules, []normSource{{Title: "Huurcommissie · Gebrekencheck", URL: huur, CheckedAt: "2026-10-29"}, {Title: "Huurcommissie · Gebrekenboek juli 2026", URL: beleid, CheckedAt: "2026-10-29"}, {Title: "NEN · Openbare toelichting conditiemeting", URL: nen, CheckedAt: "2026-10-29"}, {Title: "Rijksoverheid · Onderhoud huurwoning", URL: onderhoud, CheckedAt: "2026-10-29"}}
}
